html:
{%- set FRONT_LOCKED = ["Front Sublimation", "Front & Back sublimation", "Full sublimation"] -%}
{%- set BACK_LOCKED = ["Back Sublimation", "Front & Back sublimation", "Full sublimation"] -%}
{%- set SLEEVE_LABELS = [("Full Sleeve", "full_sleeve"), ("Half Sleeve", "half_sleeve"), ("Sleeveless", "sleeveless")] -%}
{%- set cust = customer_block(doc) -%}
<div class="vf-card">
	<style>
		.vf-card { font-family: "IBM Plex Sans", -apple-system, "Segoe UI", Roboto, sans-serif; color: #1c1a16; font-size: 11.5px; line-height: 1.3; }
		.vf-card h1 { font-family: Archivo, -apple-system, sans-serif; font-size: 16px; margin: 0; letter-spacing: .02em; }
		.vf-mono { font-family: "IBM Plex Mono", ui-monospace, monospace; }
		table.vf-layout { width: 100%; border-collapse: collapse; table-layout: fixed; }
		table.vf-layout td { vertical-align: top; padding: 0; }
		.vf-head-table td { border-bottom: 2px solid #1c1a16; padding-bottom: 6px; }
		.vf-head-left { white-space: nowrap; }
		.vf-brand-mark { width: 26px; height: 26px; vertical-align: middle; }
		.vf-title-block { display: inline-block; vertical-align: middle; margin-left: 8px; }
		.vf-sub { font-size: 9px; color: #6f6656; margin-top: 1px; text-transform: uppercase; letter-spacing: .05em; }
		.vf-meta { font-size: 11px; text-align: right; white-space: nowrap; }
		.vf-meta b { color: #2c5697; }
		.vf-cell { box-sizing: border-box; padding: 4px 8px; border: 1px solid #ddd6c7; }
		.vf-lbl { font-size: 8.5px; text-transform: uppercase; letter-spacing: .06em; color: #6f6656; }
		.vf-val { font-size: 11.5px; font-weight: 600; margin-top: 1px; }
		.vf-customer { border: 1px solid #ddd6c7; }
		.vf-customer > div { padding: 4px 8px; border-bottom: 1px solid #ddd6c7; }
		.vf-customer > div:last-child { border-bottom: none; }
		.vf-customer-name { font-size: 14px; font-weight: 700; margin-top: 1px; }
		.vf-artwork-lbl { font-size: 8.5px; text-transform: uppercase; letter-spacing: .06em; color: #6f6656; margin: 0 0 2px; }
		.vf-artwork { border: 1px solid #ddd6c7; height: 128px; text-align: center; background: #fafaf7; }
		.vf-artwork img { max-width: 92%; max-height: 118px; }
		.vf-artwork .empty { font-size: 11px; color: #9b9382; line-height: 128px; }
		.vf-team { text-align: center; margin-top: 3px; font-size: 11px; font-weight: 700; }
		.vf-hero { background: #1c1a16; color: #faf8f3; padding: 5px 10px; text-align: center; }
		.vf-hero .vf-lbl { color: #faf8f3aa; }
		.vf-hero .vf-num { font-family: "IBM Plex Mono", monospace; font-size: 17px; font-weight: 700; margin-top: 1px; }
		.vf-badge { border: 2px solid #2c5697; padding: 4px 10px; text-align: center; }
		.vf-badge .vf-lbl { color: #2c5697; }
		.vf-badge .vf-val { font-size: 12.5px; font-weight: 700; }
		.vf-section { font-size: 9.5px; text-transform: uppercase; letter-spacing: .07em; color: #6f6656;
			border-bottom: 1px solid #1c1a16; padding-bottom: 2px; margin: 8px 0 4px; font-weight: 600; }
		table.vf-strip { width: 100%; border-collapse: collapse; table-layout: fixed; border: 1px solid #ddd6c7; }
		table.vf-strip td.vf-opt-cell { border-right: 1px solid #ddd6c7; padding: 0; }
		table.vf-strip td.vf-opt-cell:last-child { border-right: none; }
		.vf-strip .vf-opt { text-align: center; padding: 4px 2px; position: relative; }
		.vf-strip .vf-name { font-size: 7.5px; color: #6f6656; text-transform: uppercase;
			min-height: 16px; line-height: 1.05; }
		.vf-strip .vf-thumb { position: relative; display: inline-block; margin: 1px auto; line-height: 0; }
		.vf-strip .vf-thumb img { display: block; width: 44px; height: 44px; }
		.vf-strip .vf-thumb svg { display: block; width: 32px; height: 32px; }
		.vf-strip .vf-opt.vf-selected { background: #ffe9a8; }
		.vf-strip .vf-opt.vf-selected .vf-name { color: #1c1a16; font-weight: 700; }
		.vf-strip .vf-mute { position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(250,248,243,.32); }
		.vf-strip .vf-opt:not(.vf-selected) .vf-name { color: #9b9382; }
		.vf-strip .vf-dot { position: absolute; top: 1px; right: 3px; width: 5px; height: 5px; border-radius: 50%; background: #c9a227; z-index: 2; }
		table.vf-cards td.vf-cell { width: 33.33%; }
		table.vf-cards td.vf-cell.blocked { background: repeating-linear-gradient(135deg, transparent, transparent 6px, #ddd6c7 6px, #ddd6c7 7px); opacity: .6; }
		table.vf-sizes { width: 100%; border-collapse: collapse; font-size: 10px; margin-top: 3px; font-family: "IBM Plex Mono", monospace; }
		table.vf-sizes th, table.vf-sizes td { border: 1px solid #ddd6c7; padding: 3px 3px; text-align: center; }
		table.vf-sizes thead th { background: #1c1a16; color: #faf8f3; font-family: "IBM Plex Sans", sans-serif; font-weight: 600; font-size: 8px; text-transform: uppercase; }
		table.vf-sizes td.rowhead, table.vf-sizes th.rowhead { text-align: left; font-family: "IBM Plex Sans", sans-serif; font-weight: 700; background: #e8eef7; color: #2c5697; }
		table.vf-sizes .totalcol { font-weight: 700; background: #1c1a16; color: #faf8f3; }
		table.vf-sizes tr.grand td { font-weight: 700; background: #f0ede3; }
		.vf-notes { border: 1px solid #ddd6c7; padding: 4px 8px; font-size: 10px; min-height: 22px; white-space: pre-wrap; }
		.vf-total-box { border: 2px solid #1c1a16; padding: 4px 10px; }
		.vf-total-box .vf-lbl { font-weight: 700; color: #1c1a16; font-size: 9.5px; }
		.vf-total-box .vf-num { font-family: "IBM Plex Mono", monospace; font-weight: 700; font-size: 14px; }
		table.vf-sign { width: 100%; margin-top: 18px; font-size: 9px; color: #6f6656; border-collapse: collapse; }
		table.vf-sign td { border-top: 1px solid #1c1a16; padding-top: 3px; }
	</style>

	<table class="vf-layout vf-head-table">
		<tr>
			<td class="vf-head-left">
				<img src="{{ brand_mark() }}" class="vf-brand-mark">
				<span class="vf-title-block">
					<h1>PRODUCTION JOB CARD</h1>
					<div class="vf-sub">{{ doc.company }} &middot; Apparel Manufacturing Floor Copy</div>
				</span>
			</td>
			<td class="vf-meta" style="width:340px">
				<b class="vf-mono">{{ doc.name }}</b> &middot;
				Order {{ frappe.format(doc.transaction_date, {"fieldtype": "Date"}) }} &middot;
				Delivery {{ frappe.format(doc.delivery_date, {"fieldtype": "Date"}) }}
			</td>
		</tr>
	</table>

	<table class="vf-layout" style="margin:8px 0">
		<tr>
			<td style="width:50%;padding-right:8px">
				<div class="vf-artwork-lbl">Artwork</div>
				<div class="vf-artwork">
					{% if doc.artwork_file %}<img src="{{ doc.artwork_file }}">{% else %}<div class="empty">No artwork attached</div>{% endif %}
				</div>
				{% if doc.team_name %}<div class="vf-team">{{ doc.team_name }}</div>{% endif %}
			</td>
			<td style="width:50%">
				<div class="vf-customer">
					<div><div class="vf-lbl">Customer</div><div class="vf-customer-name">{{ doc.customer_name or doc.customer }}</div></div>
					<div>
						<div class="vf-lbl">Address</div>
						{% for line in cust.address_lines %}<div style="font-size:11px">{{ line }}</div>{% endfor %}
					</div>
					<div><div class="vf-lbl">Mobile</div><div style="font-size:11px;font-weight:600">{{ cust.phone }}</div></div>
				</div>
				<table class="vf-layout" style="margin-top:5px"><tr>
					<td style="width:50%;padding-right:5px"><div class="vf-hero"><div class="vf-lbl">Total Qty</div><div class="vf-num">{{ doc.garment_total_qty or 0 }} Pcs</div></div></td>
					<td style="width:50%"><div class="vf-badge"><div class="vf-lbl">Product</div><div class="vf-val">{{ item_display_name(doc.product_type) }}</div></div></td>
				</tr></table>
			</td>
		</tr>
	</table>

	<div class="vf-section">Fabric &amp; Stitching</div>
	<table class="vf-layout vf-cards"><tr>
		<td class="vf-cell"><div class="vf-lbl">Fabric</div><div class="vf-val">{{ item_display_name(doc.fabric) }}</div></td>
		<td class="vf-cell"><div class="vf-lbl">Stitching</div><div class="vf-val">{{ doc.stitching_type or "-" }}{% if doc.stitching_type %}{{ stitching_icon(doc.stitching_type) | safe }}{% endif %}</div></td>
		<td class="vf-cell"><div class="vf-lbl">Buttons</div><div class="vf-val">{{ doc.button_quantity or "-" }}{% if doc.button_quantity and doc.button_quantity != "None" %}{{ button_icon(doc.button_quantity) | safe }}{% endif %}</div></td>
	</tr></table>

	<div class="vf-section">Collar Type</div>
	{{ collar_strip(doc.collar_type) | safe }}

	<div class="vf-section">Sleeve Type</div>
	{{ sleeve_strip(doc.sleeve_type) | safe }}

	<div class="vf-section">Sublimation Panels</div>
	<table class="vf-layout vf-cards">
		<tr>
			<td class="vf-cell"><div class="vf-lbl">Sublimation Type</div><div class="vf-val" style="font-size:11px">{{ doc.sublimation_type or "-" }}</div></td>
			<td class="vf-cell{% if doc.sublimation_type in FRONT_LOCKED %} blocked{% endif %}"><div class="vf-lbl">Front</div><div class="vf-val" style="font-size:11px">{% if doc.sublimation_type in FRONT_LOCKED %}Sublimation{% elif doc.front_treatment %}{{ doc.front_treatment }}{% if doc.front_colour %} &middot; {{ doc.front_colour }}{% endif %}{% else %}-{% endif %}</div></td>
			<td class="vf-cell{% if doc.sublimation_type in BACK_LOCKED %} blocked{% endif %}"><div class="vf-lbl">Back</div><div class="vf-val" style="font-size:11px">{% if doc.sublimation_type in BACK_LOCKED %}Sublimation{% elif doc.back_treatment %}{{ doc.back_treatment }}{% if doc.back_colour %} &middot; {{ doc.back_colour }}{% endif %}{% else %}-{% endif %}</div></td>
		</tr>
		<tr>
			<td class="vf-cell{% if doc.sleeve_type == 'Sleeveless' %} blocked{% endif %}"><div class="vf-lbl">Sleeve</div><div class="vf-val" style="font-size:11px">{% if doc.sleeve_type == "Sleeveless" %}n/a{% elif doc.sublimation_type == "Full sublimation" %}Sublimation{% elif doc.sleeve_treatment %}{{ doc.sleeve_treatment }}{% if doc.sleeve_colour %} &middot; {{ doc.sleeve_colour }}{% endif %}{% else %}-{% endif %}</div></td>
			<td class="vf-cell"><div class="vf-lbl">Border Colour</div><div class="vf-val" style="font-size:11px">{{ doc.border_colour or "-" }}</div></td>
			<td class="vf-cell"><div class="vf-lbl">Collar Colour</div><div class="vf-val" style="font-size:11px">{{ doc.collar_colour or "-" }}</div></td>
		</tr>
	</table>

	<div class="vf-section">Order Quantity Mix (Size &times; Sleeve)</div>
	{%- set sizes = doc.size_matrix -%}
	{% if sizes %}
	<table class="vf-sizes">
		<thead>
			<tr>
				<th class="rowhead">Sleeve Type</th>
				{% for row in sizes %}<th>{{ row.size }}</th>{% endfor %}
				<th class="totalcol">Total</th>
			</tr>
		</thead>
		<tbody>
			{% if doc.sleeve_type == "Multi" %}
				{% for label, field in SLEEVE_LABELS %}
					{% set row_qtys = sizes | map(attribute=field) | map("int") | list %}
					{% set row_sum = row_qtys | sum %}
					{% if row_sum > 0 %}
						<tr>
							<td class="rowhead">{{ label }}</td>
							{% for qty in row_qtys %}<td>{{ qty }}</td>{% endfor %}
							<td class="totalcol">{{ row_sum }}</td>
						</tr>
					{% endif %}
				{% endfor %}
				<tr class="grand">
					<td class="rowhead">Grand Total</td>
					{% for row in sizes %}<td>{{ row.row_total or 0 }}</td>{% endfor %}
					<td class="totalcol">{{ doc.garment_total_qty or 0 }}</td>
				</tr>
			{% else %}
				<tr>
					<td class="rowhead">{{ doc.sleeve_type or "-" }}</td>
					{% for row in sizes %}<td>{{ row.row_total or 0 }}</td>{% endfor %}
					<td class="totalcol">{{ doc.garment_total_qty or 0 }}</td>
				</tr>
			{% endif %}
		</tbody>
	</table>
	{% else %}
	<div style="font-size:11px;color:#9b9382">No quantities entered.</div>
	{% endif %}

	<table class="vf-layout" style="margin-top:6px"><tr>
		<td style="padding-right:10px"><div class="vf-notes"><div class="vf-lbl" style="margin-bottom:2px">Notes</div>{% if doc.vf_notes %}{{ doc.vf_notes }}{% endif %}</div></td>
		<td style="width:120px"><div class="vf-total-box"><div class="vf-lbl">TOTAL</div><div class="vf-num">{{ doc.garment_total_qty or 0 }}</div></div></td>
	</tr></table>

	<table class="vf-sign"><tr>
		<td>Sublimation &amp; Printing</td>
		<td>Cutting Floor</td>
		<td>Sewing &amp; Assembly</td>
		<td>QC</td>
		<td>Packing</td>
	</tr></table>
</div>
